module parity_8bit (
    input [7:0] in,
    output out
);

    wire w1, w2, w3, w4, w5, w6;

    assign w1 = in[1] ^ in[0];
    assign w2 = in[3] ^~ in[2];
    assign w3 = in[5] ^ in[4];
    assign w4 = in[7] ^~ in[6];
    assign w5 = w1 ^ w2;
    assign w6 = w3 ^ w4;
    assign out = w5 ^ w6;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire sel0_bar, sel1_bar;
    wire [3:0] and_out;
    wire [1:0] or_intermediate;

    not (sel0_bar, sel[0]);
    not (sel1_bar, sel[1]);

    and (and_out[0], in[0], sel1_bar, sel0_bar);
    and (and_out[1], in[1], sel1_bar, sel[0]);
    and (and_out[2], in[2], sel[1], sel0_bar);
    and (and_out[3], in[3], sel[1], sel[0]);

    or (or_intermediate[0], and_out[0], and_out[1]);
    or (or_intermediate[1], and_out[2], and_out[3]);
    or (out, or_intermediate[0], or_intermediate[1]);

endmodule

module majority (
    input a, b, c,
    output out
);
    assign out = (a & b) | (b & c) | (a & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire eq0, eq1, eq2, eq3;
    assign eq0 = a[0] ~^ b[0];
    assign eq1 = a[1] ~^ b[1];
    assign eq2 = a[2] ~^ b[2];
    assign eq3 = a[3] ~^ b[3];
    assign equal = eq0 & eq1 & eq2 & eq3;
endmodule

