module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg top, bottom;
    wire top_d, bottom_d;
    wire and_out, or_out;

    assign and_out = reset & bottom;
    assign or_out = reset | and_out;
    assign top_d = ~top;
    assign bottom_d = top ^ bottom ^ or_out;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            top <= 1'b0;
            bottom <= 1'b0;
        end else begin
            top <= top_d;
            bottom <= bottom_d;
        end
    end

    assign state = {top, bottom};

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg Q_A, Q_B, Q_C;
    wire D_A, D_B, D_C;

    assign D_A = Q_B & ~Q_C;
    assign D_B = ~Q_A & ~Q_C;
    assign D_C = Q_A | Q_B;

    always @(posedge clk or negedge reset) begin
        if (!reset) begin
            Q_A <= 1'b0;
            Q_B <= 1'b0;
            Q_C <= 1'b0;
        end else begin
            Q_A <= D_A;
            Q_B <= D_B;
            Q_C <= D_C;
        end
    end

    assign light[0] = ~Q_A & Q_B;
    assign light[1] = Q_A & ~Q_B;
    assign light[2] = Q_A & Q_B;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        case (current_state)
            2'b00: begin
                if (up_request) next_state = 2'b01;
                else if (down_request) next_state = 2'b10;
                else next_state = 2'b00;
            end
            2'b01: begin
                if (down_request) next_state = 2'b10;
                else if (up_request) next_state = 2'b01;
                else next_state = 2'b01;
            end
            2'b10: begin
                if (up_request) next_state = 2'b01;
                else if (down_request) next_state = 2'b10;
                else next_state = 2'b10;
            end
            default: next_state = 2'b00;
        endcase
    end

    assign state = current_state;
endmodule

