module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);
    wire [8:0] borrow;
    wire [7:0] diff_bits;
    assign borrow[0] = 1'b0;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : sub
            assign diff_bits[i] = a[i] ^ b[i] ^ borrow[i];
            assign borrow[i+1] = (~a[i] & b[i]) | (~a[i] & borrow[i]) | (b[i] & borrow[i]);
        end
    endgenerate

    assign diff = {borrow[8], diff_bits};
endmodule

