module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    wire [7:0] d = data_in;
    wire [7:0] q;

    assign q[0] = d[1] ^ (d[3] & d[4]);
    assign q[1] = d[2];
    assign q[2] = d[1] ^ (d[3] & d[4]);
    assign q[3] = d[2] ^ (d[5] | (d[3] & d[4]));
    assign q[4] = d[7];
    assign q[5] = d[6] ^ ~(~(~(d[1] & d[0])) & ~(~(d[3] & d[4])) & d[7]);
    assign q[6] = d[5] ^ (d[4] ^ d[0]);
    assign q[7] = d[0] ^ ~((d[4] | d[6]) & d[7]);

