module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire eq0, eq1, eq2, eq3;
    wire gt0, gt1, gt2, gt3;
    wire lt0, lt1, lt2, lt3;

    // Bit-wise comparisons
    assign eq0 = ~(a[0] ^ b[0]);
    assign eq1 = ~(a[1] ^ b[1]);
    assign eq2 = ~(a[2] ^ b[2]);
    assign eq3 = ~(a[3] ^ b[3]);

    assign gt0 = a[0] & ~b[0];
    assign gt1 = a[1] & ~b[1];
    assign gt2 = a[2] & ~b[2];
    assign gt3 = a[3] & ~b[3];

    assign lt0 = ~a[0] & b[0];
    assign lt1 = ~a[1] & b[1];
    assign lt2 = ~a[2] & b[2];
    assign lt3 = ~a[3] & b[3];

    // Overall equality
    assign eq = eq3 & eq2 & eq1 & eq0;

    // Overall greater-than
    assign gt = gt3 |
                (eq3 & gt2) |
                (eq3 & eq2 & gt1) |
                (eq3 & eq2 & eq1 & gt0);

    // Overall less-than
    assign lt = lt3 |
                (eq3 & lt2) |
                (eq3 & eq2 & lt1) |
                (eq3 & eq2 & eq1 & lt0);

endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

    // Internal signals
    wire not_in1;
    wire not_in0;
    wire nor_in;

    // Inverters
    assign not_in1 = ~in[1];
    assign not_in0 = ~in[0];

    // NOR gate for out[0] logic
    assign nor_in = ~(in[1] | in[0]);

    // Output assignments based on circuit diagram
    assign out[0] = enable & not_in1 & nor_in;
    assign out[1] = enable & not_in1 & in[0];
    assign out[2] = enable & in[1] & not_in0;
    assign out[3] = enable & in[1] & in[0];

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);
    wire in0, in1, in2;
    wire not_in0, not_in1, not_in2;
    wire enable_bar;
    wire and0, and1, and2, and3, and4, and5, and6, and7;

    assign in0 = in[0];
    assign in1 = in[1];
    assign in2 = in[2];

    not (not_in0, in0);
    not (not_in1, in1);
    not (not_in2, in2);
    not (enable_bar, enable);

    and (and0, enable_bar, not_in2, not_in1, not_in0);
    and (and1, enable_bar, not_in2, not_in1, in0);
    and (and2, enable_bar, not_in2, in1, not_in0);
    and (and3, enable_bar, not_in2, in1, in0);
    and (and4, enable_bar, in2, not_in1, not_in0);
    and (and5, enable_bar, in2, not_in1, in0);
    and (and6, enable_bar, in2, in1, not_in0);
    and (and7, enable_bar, in2, in1, in0);

    assign out[0] = ~and0;
    assign out[1] = ~and1;
    assign out[2] = ~and2;
    assign out[3] = ~and3;
    assign out[4] = ~and4;
    assign out[5] = ~and5;
    assign out[6] = ~and6;
    assign out[7] = ~and7;
endmodule

