module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  // Internal wires and registers
  reg q0, q1, q2;
  wire nq0, nq1, nq2;
  wire w1, w2, w3, w4, w5, w6, w7, w8, w9, w10;
  wire w11, w12, w13, w14, w15, w16, w17, w18, w19, w20;
  wire w21, w22, w23, w24, w25, w26, w27, w28, w29, w30;
  wire w31, w32, w33, w34, w35, w36, w37, w38, w39, w40;
  wire w41, w42, w43, w44, w45, w46, w47, w48, w49, w50;
  wire w51, w52, w53, w54, w55, w56, w57, w58, w59, w60;

  // Flip-flop outputs
  assign nq0 = ~q0;
  assign nq1 = ~q1;
  assign nq2 = ~q2;

  // Combinational logic for flip-flop inputs
  assign w1 = r[0] & nq2;
  assign w2 = r[1] & q2;
  assign w3 = w1 | w2;
  assign w4 = r[1] & nq1;
  assign w5 = r[0] & q1;
  assign w6 = w4 | w5;
  assign w7 = r[2] & q0;
  assign w8 = w6 & w7;
  assign w9 = w3 | w8;

  assign w10 = r[2] & nq0;
  assign w11 = r[1] & q0;
  assign w12 = w10 | w11;
  assign w13 = r[0] & nq1;
  assign w14 = r[2] & q1;
  assign w15 = w13 | w14;
  assign w16 = w12 & w15;
  assign w17 = r[0] & q2;
  assign w18 = w16 | w17;

  assign w19 = r[1] & nq0;
  assign w20 = r[0] & q0;
  assign w21 = w19 | w20;
  assign w22 = r[2] & nq1;
  assign w23 = w21 & w22;
  assign w24 = r[2] & q2;
  assign w25 = w23 | w24;

  // Sequential logic
  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      q0 <= 1'b0;
      q1 <= 1'b0;
      q2 <= 1'b0;
    end else begin
      q0 <= w9;
      q1 <= w18;
      q2 <= w25;
    end
  end

  // Output logic for g[0]
  assign w26 = nq0 & nq1;
  assign w27 = q0 & q1;
  assign w28 = w26 | w27;
  assign w29 = nq2 & w28;
  assign w30 = q2 & r[0];
  assign g[0] = w29 | w30;

  // Output logic for g[1]
  assign w31 = q0 & nq1;
  assign w32 = nq0 & q1;
  assign w33 = w31 | w32;
  assign w34 = nq2 & w33;
  assign w35 = q2 & r[1];
  assign g[1] = w34 | w35;

  // Output logic for g[2]
  assign w36 = nq0 & nq1;
  assign w37 = q0 & q1;
  assign w38 = w36 | w37;
  assign w39 = q2 & w38;
  assign w40 = nq2 & r[2];
  assign g[2] = w39 | w40;

endmodule

