module TopModule (
  input [2:0] a,
  output reg [15:0] q
);

  // Internal signals for clarity
  wire a0, a1, a2;
  assign {a2, a1, a0} = a;

  // Each output bit is derived from the combinational logic shown in the diagram
  always @(*) begin
    // q[0]
    q[0] = ~a2 & ~a1 & ~a0;
    // q[1]
    q[1] = ~a2 & ~a1 & a0;
    // q[2]
    q[2] = ~a2 & a1 & ~a0;
    // q[3]
    q[3] = ~a2 & a1 & a0;
    // q[4]
    q[4] = a2 & ~a1 & ~a0;
    // q[5]
    q[5] = a2 & ~a1 & a0;
    // q[6]
    q[6] = a2 & a1 & ~a0;
    // q[7]
    q[7] = a2 & a1 & a0;
    // q[8]
    q[8] = ~a2 & ~a1;
    // q[9]
    q[9] = ~a2 & ~a0;
    // q[10]
    q[10] = ~a2 & a1;
    // q[11]
    q[11] = ~a2 & a0;
    // q[12]
    q[12] = a2 & ~a1;
    // q[13]
    q[13] = a2 & ~a0;
    // q[14]
    q[14] = a2 & a1;
    // q[15]
    q[15] = a2 & a0;
  end

endmodule

