module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  reg [3:0] d;
  wire [3:0] q_next;

  // D input logic for each flip-flop based on the circuit diagram
  assign q_next[0] = ~q[3];
  assign q_next[1] = ~(q[0] & ~q[3]);
  assign q_next[2] = q[1] ^ ~(q[0] & q[3]);
  assign q_next[3] = (q[2] ^ q[0]) | (q[1] ^ q[3]);

  // Sequential logic for the four flip-flops
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q <= 4'b0000;
    end else begin
      q <= q_next;
    end
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);
  wire and1_out = train_valid & train_taken;
  wire or1_out = and1_out | q2;
  wire and2_out = and1_out & q1;
  reg q1, q2;

  // DFFE_PP1P: Asynchronous reset D flip-flop with enable
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      q1 <= 1'b0;
    end else if (or1_out) begin
      q1 <= and1_out;
    end
  end

  // S_DFFE_PPOP: Asynchronous reset D flip-flop with set, enable
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      q2 <= 1'b0;
    end else if (and2_out) begin
      if (q1) begin
        q2 <= 1'b1;
      end else begin
        q2 <= and1_out;
      end
    end
  end

  // State output logic
  assign state[1] = q1;
  assign state[0] = and1_out ? q2 : 1'b0;
endmodule

