module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire [4:0] sum_internal;
  wire [3:0] p, g; // propagate and generate signals
  wire [4:0] c;    // carry signals

  // Generate and propagate for 4-bit addition
  assign p = x ^ y;
  assign g = x & y;

  // Carry lookahead logic
  assign c[0] = 1'b0; // initial carry in
  assign c[1] = g[0] | (p[0] & c[0]);
  assign c[2] = g[1] | (p[1] & g[0]) | (p[1] & p[0] & c[0]);
  assign c[3] = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]) | (p[2] & p[1] & p[0] & c[0]);
  assign c[4] = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]) | (p[3] & p[2] & p[1] & p[0] & c[0]);

  // Sum calculation
  assign sum_internal[0] = p[0] ^ c[0];
  assign sum_internal[1] = p[1] ^ c[1];
  assign sum_internal[2] = p[2] ^ c[2];
  assign sum_internal[3] = p[3] ^ c[3];
  assign sum_internal[4] = c[4];

  assign sum = sum_internal;

endmodule

