  end

  // Second flip-flop
  always @(posedge clk or negedge resetn) begin
    if (!resetn)
      q1 <= 1'b0;
    else
      q1 <= q0;
  end

  // Third flip-flop
  always @(posedge clk or negedge resetn) begin
    if (!resetn)
      q2 <= 1'b0;
    else
      q2 <= q1;
  end

  // Fourth flip-flop
  always @(posedge clk or negedge resetn) begin
    if (!resetn)
      q3 <= 1'b0;
    else
      q3 <= q2;
  end

  assign out = q3;
endmodule

module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  reg [3:0] state;
  reg [3:0] next_state;

  // 时序逻辑，描述状态寄存器
  always @(posedge clk or negedge reset) begin
    if (!reset) begin
      state <= 4'b0000;
    end else begin
      state <= next_state;
    end
  end

  // 组合逻辑，描述状态转移
  always @(*) begin
    next_state[0] = (state[3] & state[2]) | (state[1] & state[0]) | w;
    next_state[1] = (state[3] & !state[2]) | (state[1] & !state[0]) | (!state[3] & !state[1] & w);
    next_state[2] = (state[3] & state[1]) | (!state[2] & state[0]) | (!state[3] & !state[0] & w);
    next_state[3] = (state[2] & state[1]) | (!state[3] & !state[2] & !state[0] & w);
  end

  // 输出逻辑
  assign z = (state[3] & state[0]) | (state[2] & state[1]) | (!state[3] & !state[2] & !state[1] & !state[0] & w);

endmodule

