);
  wire w1, w2, w3;

  // AND gates
  and g1 (w1, a, b);
  and g2 (w2, c, d);

  // NOR gate for 'out'
  nor g3 (out, w1, w2);

  // NAND gate (output w3 is unconnected)
  nand g4 (w3, w1, w2);

