module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

reg q1, q2, q3;

// Flip-flop 1 D input (NOR gate)
wire d1 = ~(q1 | q2);
// Flip-flop 2 D input (NAND gate)
wire d2 = ~(q1 & q2);

// Intermediate signals for Flip-flop 3 D input
wire ff3_int1 = q1 | w;
wire ff3_int2 = q2 | ~q3;
wire ff3_int3 = ff3_int1 & ff3_int2;
wire ff3_int4 = q3 & ~w;
// Flip-flop 3 D input (NOR gate)
wire d3 = ~(ff3_int3 | ff3_int4);

// Output z logic
wire z_int = (q1 | q3) & (q2 | ~q3);
assign z = ~z_int;

// Positive edge-triggered D flip-flops with asynchronous active-high reset
always @(posedge clk or posedge reset) begin
  if (reset) begin
    q1 <= 1'b0;
    q2 <= 1'b0;
    q3 <= 1'b0;
  end else begin
    q1 <= d1;
    q2 <= d2;
    q3 <= d3;
  end
end

endmodule

module TopModule (
  input clk,
  input x,
  input [2:0] y,
  output reg Y0,
  output reg z
);

wire not_y2 = ~y[2];
wire not_y0 = ~y[0];

wire nand1_out = ~(not_y2 & y[1]);
wire nor1_out = ~(y[1] | not_y0);
wire and1_out = y[0] & nor1_out;
wire mux1_out = x ? and1_out : nor1_out;
wire or1_out = nand1_out | mux1_out;

always @(*) begin
    z = ~(mux1_out | x);
    Y0 = x ? x : or1_out;
end

endmodule

