module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  reg q1, q2, q3;
  wire nand_out, or_out, nor_out;
  reg final_q;

  // First three flip-flops (positive edge-triggered)
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q1 <= 1'b0;
      q2 <= 1'b0;
      q3 <= 1'b0;
    end else begin
      q1 <= data;
      q2 <= q1;
      q3 <= q2;
    end
  end

  // Combinational logic
  assign nand_out = ~(q2 & q3);
  assign or_out = data | q1;
  assign nor_out = ~(nand_out | or_out);

  // Final flip-flop (negative edge-triggered)
  always @(negedge clk or posedge reset) begin
    if (reset) begin
      final_q <= 1'b0;
    end else begin
      final_q <= nor_out;
    end
  end

  assign start_shifting = final_q;

endmodule

