  output logic f
);
  wire and_out, or1_out, or2_out, nand_out;

  assign and_out = x[3] & x[1];
  assign or1_out = x[1] | x[2];
  assign or2_out = x[2] | x[0];
  assign nand_out = ~(and_out & or1_out);
  assign f = nand_out | or2_out;

endmodule

module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  reg a, b, c, d, e, h, i, j, k, l, m, n, o, p, q, r;

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      a <= 1'b0;
      b <= 1'b0;
      c <= 1'b0;
      d <= 1'b0;
      e <= 1'b0;
      h <= 1'b0;
      i <= 1'b0;
      j <= 1'b0;
      k <= 1'b0;
      l <= 1'b0;
      m <= 1'b0;
      n <= 1'b0;
      o <= 1'b0;
      p <= 1'b0;
      q <= 1'b0;
      r <= 1'b0;
    end else begin
      a <= ~y;
      b <= ~(a & x);
      c <= b & a;
      d <= ~c;
      e <= ~(d & x);
      h <= e | b;
      i <= ~h;
      j <= i & x;
      k <= ~(j & h);
      l <= ~k;
      m <= l | e;
      n <= ~(m & x);
      o <= ~n;
      p <= o & h;
      q <= ~(p & l);
      r <= ~q;
    end
  end

  assign f = ~(l & e);
  assign g = r & (o | h);

endmodule

module TopModule (
  input clock,
  input a,
  output reg p,
  output reg q
);
    // D latch behavior: when clock is high, p follows a; otherwise p holds value
    always @(a or clock) begin
        if (clock)
            p <= a;
    end

    // q is the inverse of p
    always @(p) begin
        q <= ~p;
    end
endmodule

module TopModule (
  input clk,
  input x,
  output z
);

  reg q;

  always @(posedge clk) begin
    q <= x;
  end

  assign z = q;

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [4:0] q
);

  // Internal signals
  wire xor_out;
  reg [4:0] d;

  // D flip-flops with synchronous reset
  always @(posedge clk) begin
    if (reset) begin
      q <= 5'b0;
    end else begin
      q <= d;
    end
  end

  // Combinational logic for next state
  always @(*) begin
    d[0] = q[4];
    d[1] = q[0];
    d[2] = q[1];
    d[3] = q[2];
    d[4] = xor_out;
  end

  // XOR gate
  assign xor_out = q[3] ^ q[1];

endmodule

module TopModule (
  input [3:0] x,
  output logic f
);

assign f = ~( (~ (x[2] & x[0])) | (x[1] & x[3]) );

endmodule

module cla_16bit(
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output [15:0] S,
    output Cout
);
    // Behavioral description of 16-bit CLA adder
    assign {Cout, S} = A + B + Cin;
endmodule

module adder_32bit(A,B,S,C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire [15:0] A_low, B_low, S_low;
    wire [15:0] A_high, B_high, S_high;
    wire C16; // carry out from lower 16-bit adder

    // Split the 32-bit inputs into lower and upper 16-bit parts
    assign A_low = A[16:1];
    assign A_high = A[32:17];
    assign B_low = B[16:1];
    assign B_high = B[32:17];

    // Lower 16-bit CLA with Cin = 0
    cla_16bit lower_adder(
        .A(A_low),
        .B(B_low),
        .Cin(1'b0),
        .S(S_low),
        .Cout(C16)
    );

    // Upper 16-bit CLA with Cin from lower adder
    cla_16bit upper_adder(
        .A(A_high),
        .B(B_high),
        .Cin(C16),
        .S(S_high),
        .Cout(C32)
    );

    // Combine the sum outputs
    assign S[16:1] = S_low;
    assign S[32:17] = S_high;

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [8:0] carry;
    assign carry[0] = cin;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : gen_adder
            assign sum[i] = a[i] ^ b[i] ^ carry[i];
            assign carry[i+1] = (a[i] & b[i]) | (a[i] & carry[i]) | (b[i] & carry[i]);
        end
    endgenerate

    assign cout = carry[8];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);
    // 内部连线
    wire [4:0] bin_sum; // 二进制加法结果（5位以容纳进位）
    wire [4:0] adj_sum; // 调整后的结果
    wire       carry_out_raw; // 原始进位
    wire       need_adjust;  // 需要调整的标志（结果>9或产生进位）

    // 第一步：进行二进制加法
    assign bin_sum = A + B + Cin;

    // 第二步：判断是否需要进行BCD调整
    // 条件1：二进制和大于9 (1010)
    // 条件2：二进制和产生了第5位的进位（即>=16，但BCD输入限制了这种情况，主要是条件1）
    assign need_adjust = (bin_sum > 9);

    // 第三步：根据是否需要调整，计算最终的和与进位
    assign adj_sum = need_adjust ? (bin_sum + 4'd6) : bin_sum; // 加6调整
    assign Cout = need_adjust; // 当需要调整时，产生进位

    // 第四步：截取低4位作为最终的BCD和
    assign Sum = adj_sum[3:0];

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

wire gt3, eq3, lt3;
wire gt2, eq2, lt2;
wire gt1, eq1, lt1;
wire gt0, eq0, lt0;

assign gt3 = A[3] & ~B[3];
assign lt3 = ~A[3] & B[3];
assign eq3 = ~(A[3] ^ B[3]);

assign gt2 = A[2] & ~B[2];
assign lt2 = ~A[2] & B[2];
assign eq2 = ~(A[2] ^ B[2]);

assign gt1 = A[1] & ~B[1];
assign lt1 = ~A[1] & B[1];
assign eq1 = ~(A[1] ^ B[1]);

assign gt0 = A[0] & ~B[0];
assign lt0 = ~A[0] & B[0];
assign eq0 = ~(A[0] ^ B[0]);

assign A_equal = eq3 & eq2 & eq1 & eq0;
assign A_greater = gt3 | (eq3 & gt2) | (eq3 & eq2 & gt1) | (eq3 & eq2 & eq1 & gt0);
assign A_less = lt3 | (eq3 & lt2) | (eq3 & eq2 & lt1) | (eq3 & eq2 & eq1 & lt0);

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg a_prev;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_prev <= 1'b0;
        rise   <= 1'b0;
        down   <= 1'b0;
    end
    else begin
        a_prev <= a;
        rise   <= a & ~a_prev;
        down   <= ~a & a_prev;
    end
end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [2:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 3'd0;
            clk_div <= 1'b0;
        end else begin
            if (count == NUM_DIV/2 - 1) begin
                count <= 3'd0;
                clk_div <= ~clk_div;
            end else begin
                count <= count + 1;
            end
        end
    end

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

  // Internal 16-bit register
  reg [15:0] reg_data;

  // Enable signal: AND of both fetch bits
  wire en = fetch[0] & fetch[1];

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      reg_data <= 16'b0;
    end else if (en) begin
      // Load data into specific positions based on circuit diagram
      // This mapping is derived from the visual connections in the schematic
      reg_data[15] <= data[5];
      reg_data[14] <= data[6];
      reg_data[13] <= data[7];
      reg_data[12] <= data[0];
      reg_data[11] <= data[1];
      reg_data[10] <= data[2];
      reg_data[9]  <= data[3];
      reg_data[8]  <= data[4];
      // Lower 8 bits are shifted internally (based on diagram feedback connections)
      reg_data[7]  <= reg_data[15];
      reg_data[6]  <= reg_data[14];
      reg_data[5]  <= reg_data[13];
      reg_data[4]  <= reg_data[12];
      reg_data[3]  <= reg_data[11];
      reg_data[2]  <= reg_data[10];
      reg_data[1]  <= reg_data[9];
      reg_data[0]  <= reg_data[8];
    end
  end

  // Output assignments
  assign ins = reg_data[15:13];
  assign ad1 = reg_data[12:8];
  assign ad2 = reg_data[7:0];

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;
  reg q0, q1, q2, q3;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      q0 <= 0;
      q1 <= 0;
      q2 <= 0;
      q3 <= 0;
    end else begin
      q0 <= q0 ^ q1;
      q1 <= q0;
      q2 <= q1;
      q3 <= q2;
    end
  end

  always @(*) begin
    out = {q3, q2, q1, q0};
  end
endmodule

module right_shifter(clk, q, d);
    input clk;
    input d;
    output [7:0] q;

    reg [8:0] shift_reg;

    always @(posedge clk) begin
        shift_reg[8] <= d;
        shift_reg[7] <= shift_reg[8];
        shift_reg[6] <= shift_reg[7];
        shift_reg[5] <= shift_reg[6];
        shift_reg[4] <= shift_reg[5];
        shift_reg[3] <= shift_reg[4];
        shift_reg[2] <= shift_reg[3];
        shift_reg[1] <= shift_reg[2];
        shift_reg[0] <= shift_reg[1];
    end

    assign q = shift_reg[7:0];
endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg en_a;
reg en_b;
reg [3:0] data_b;

// Enable synchronization from clk_a to clk_b
always @(posedge clk_a or negedge arstn) begin
    if (!arstn)
        en_a <= 1'b0;
    else
        en_a <= data_en;
end

always @(posedge clk_b or negedge brstn) begin
    if (!brstn)
        en_b <= 1'b0;
    else
        en_b <= en_a;
end

// Data synchronization in clk_b domain
always @(posedge clk_b or negedge brstn) begin
    if (!brstn)
        data_b <= 4'b0;
    else
        data_b <= data_in;
end

// Output with enable gating
always @(posedge clk_b or negedge brstn) begin
    if (!brstn)
        dataout <= 4'b0;
    else if (en_b)
        dataout <= data_b;
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    wire [6:0] q;
    reg [6:0] dff_d;
    wire [6:0] dff_q;
    wire [3:0] d_wire;
    wire not_q2, not_q6;
    wire and1_out, and2_out, and3_out, or1_out, nand1_out;

    assign d_wire = d;

    // DFF instances
    s_dff_pno dff0 (.clk(clk), .rst_n(rst_n), .d(dff_d[0]), .q(dff_q[0]));
    s_dff_pno dff1 (.clk(clk), .rst_n(rst_n), .d(dff_d[1]), .q(dff_q[1]));
    s_dff_pno dff2 (.clk(clk), .rst_n(rst_n), .d(dff_d[2]), .q(dff_q[2]));
    s_dff_pno dff3 (.clk(clk), .rst_n(rst_n), .d(dff_d[3]), .q(dff_q[3]));
    s_dff_pno dff4 (.clk(clk), .rst_n(rst_n), .d(dff_d[4]), .q(dff_q[4]));
    s_dff_pno dff5 (.clk(clk), .rst_n(rst_n), .d(dff_d[5]), .q(dff_q[5]));
    s_dff_pno dff6 (.clk(clk), .rst_n(rst_n), .d(dff_d[6]), .q(dff_q[6]));

    // Logic gates and connections based on diagram
    assign not_q2 = ~dff_q[2];
    assign not_q6 = ~dff_q[6];

    assign and1_out = dff_q[1] & dff_q[0];
    assign and2_out = dff_q[3] & dff_q[2];
    assign and3_out = dff_q[5] & dff_q[4];

    assign or1_out = dff_q[0] | dff_q[2];
    assign nand1_out = ~(dff_q[1] & dff_q[0]);

    // Multiplexer logic for D inputs
    always @(*) begin
        dff_d[0] = not_q2 & and1_out;
        dff_d[1] = nand1_out;
        dff_d[2] = and1_out & not_q6;
        dff_d[3] = or1_out;
        dff_d[4] = and2_out;
        dff_d[5] = and3_out;
        dff_d[6] = and2_out & and3_out;
    end

    assign valid_out = dff_q[6];
    assign dout = dff_q[5];

endmodule

module s_dff_pno(
    input clk,
    input rst_n,
    input d,
    output reg q
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            q <= 1'b0;
        end else begin
            q <= d;
        end
    end
endmodule

module ROM (
    input wire [7:0] addr,        // 8-bit Address input
    output reg [15:0] dout        // 16-bit Data output
);

    always @(*) begin
        case (addr[3:0])
            4'h0:   dout = 16'h0000;
            4'h1:   dout = 16'h0000;
            4'h2:   dout = 16'h0000;
            4'h3:   dout = 16'h0000;
            4'h4:   dout = 16'h0000;
            4'h5:   dout = 16'h0000;
            4'h6:   dout = 16'h0000;
            4'h7:   dout = 16'h0000;
            4'h8:   dout = 16'h0000;
            4'h9:   dout = 16'h0000;
            4'hA:   dout = 16'h0000;
            4'hB:   dout = 16'h0000;
            4'hC:   dout = 16'h0000;
            4'hD:   dout = 16'h0000;
            4'hE:   dout = 16'h0000;
            4'hF:   dout = 16'h8000;
            default: dout = 16'h0000;
        endcase
    end

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

    // Internal signals
    wire q0, q1, q2, q3, q4;
    wire d0, d1, d2, d3, d4;

    // D flip-flop instances
    // Top right DFF (q0)
    dff dff0(
        .clk(clk),
        .rst_n(rst_n),
        .d(d0),
        .q(q0)
    );

    // Top middle DFF (q1)
    dff dff1(
        .clk(clk),
        .rst_n(rst_n),
        .d(d1),
        .q(q1)
    );

    // Bottom left DFF (q2)
    dff dff2(
        .clk(clk),
        .rst_n(rst_n),
        .d(d2),
        .q(q2)
    );

    // Middle DFF (q3)
    dff dff3(
        .clk(clk),
        .rst_n(rst_n),
        .d(d3),
        .q(q3)
    );

    // Right DFF (q4)
    dff dff4(
        .clk(clk),
        .rst_n(rst_n),
        .d(d4),
        .q(q4)
    );

    // Combinational logic for D inputs
    assign d0 = ~(q0 & ~(q1 & q4));
    assign d1 = ~(q2 & q3);
    assign d2 = ~(data_in & q0);
    assign d3 = q0 & q1 & q2;
    assign d4 = ~(q3 & (q0 | q1));

    // Output logic
    assign sequence_detected = ~(q0 | q4);

endmodule

// D flip-flop module
module dff(
    input clk,
    input rst_n,
    input d,
    output reg q
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            q <= 1'b0;
        else
            q <= d;
    end
endmodule
